select bc.id, bc.book_id as bookId, bc.chapter_name as chapterName, bi.book_name as bookName, bc.chapter_content as chapterContent, bc.word_count as wordCount, bc.update_time as updateTime from book_chapter bc left join book_info bi on bc.book_id = bi.id where bc.book_id in
#{bookId}
and bc.chapter_status = 0 order by bc.update_time desc

select bc.id,
       bi.book_name       as bookName,
       bc.chapter_name    as chapterName,
       bc.chapter_content as chapterContent,
       bc.word_count      as wordCount
from book_chapter bc
         inner join book_info bi on bc.book_id = bi.id
where bc.id = #{chapterId}
  and bc.book_id = #{bookId}
  and bi.author_id = #{authorId}

mapper.update:
update book_chapter bc
inner join book_info bi on bc.book_id = bi.id
set bc.chapter_status = 0,
    bc.update_time = now()
where bc.id = #{chapterId}
and bc.book_id = #{bookId}
and bi.author_id = #{authorId}
and bc.chapter_status = 3

mapper.delete:
